using Minecraft.Physics;
using Minecraft.Schemas.Shapes;
using Minecraft.Schemas.Vec;

namespace ManagedServer.Testing.Physics;

/// <summary>
/// The collision sweep has to agree with the vanilla client to the bit: a client predicting an
/// entity's motion locally drifts away from the server the moment it does not.
/// <p/>
/// Both fixtures below were produced by running vanilla's own <c>Entity.collideWithShapes</c> out of
/// the 26.2 server jar over the same inputs, the way <see cref="LpVec3Test"/> pins its encodings, and
/// are committed as regression cases. They came out of a 20,000 case fuzz run that matched exactly.
/// </summary>
[TestFixture]
public class EntityCollisionTest {
    /// <summary>
    /// A readable scene: a floor, a slab to the east, a stairs shaped pair to the south, a fence post
    /// to the west that leaves its own block, and a ceiling block.
    /// </summary>
    private static List<Box> BuildScene() {
        List<Box> scene = [];

        for (int x = -1; x <= 2; x++) {
            for (int z = -1; z <= 2; z++) {
                scene.Add(new Box(x, -1, z, x + 1, 0, z + 1));
            }
        }

        scene.Add(new Box(2, 0, 0, 3, 0.5, 1));                   // slab
        scene.Add(new Box(0, 0, 2, 1, 0.5, 3));                   // stairs, lower step
        scene.Add(new Box(0, 0.5, 2, 1, 1, 2.5));                 // stairs, upper step
        scene.Add(new Box(-0.625, 0, 0.375, -0.375, 1.5, 0.625)); // fence post
        scene.Add(new Box(1, 2, 1, 2, 3, 2));                     // ceiling

        return scene;
    }

    /// <summary>box min and size, movement, then the movement vanilla resolved it to.</summary>
    private record SceneCase(
        double BoxX, double BoxY, double BoxZ, double SizeX, double SizeY, double SizeZ,
        double MoveX, double MoveY, double MoveZ,
        double ResultX, double ResultY, double ResultZ);

