    [Test]
    public void TestSweepMatchesVanilla() {
        List<Box> scene = BuildScene();

        foreach (SceneCase c in SceneCases) {
            Box box = new(c.BoxX, c.BoxY, c.BoxZ, c.BoxX + c.SizeX, c.BoxY + c.SizeY, c.BoxZ + c.SizeZ);
            Vec3<double> movement = new(c.MoveX, c.MoveY, c.MoveZ);

            Vec3<double> result = EntityPhysics.CollideWithShapes(movement, box, scene);

            Assert.Multiple(() => {
                Assert.That(result.X, Is.EqualTo(c.ResultX), $"X moving {movement} from {box.MinX},{box.MinY},{box.MinZ}");
                Assert.That(result.Y, Is.EqualTo(c.ResultY), $"Y moving {movement} from {box.MinX},{box.MinY},{box.MinZ}");
                Assert.That(result.Z, Is.EqualTo(c.ResultZ), $"Z moving {movement} from {box.MinX},{box.MinY},{box.MinZ}");
            });
        }
    }

