    [Test]
    public void TestSweepMatchesVanillaOnBlockShapes() {
        foreach (string line in GeneratedCases) {
            string[] parts = line.Split('|');

            List<Box> shapes = [];
            foreach (string shapeText in parts[0].Split(';')) {
                double[] s = Numbers(shapeText);
                Aabb local = new(
                    new Vec3<double>(s[0], s[1], s[2]),
                    new Vec3<double>(s[3] - s[0], s[4] - s[1], s[5] - s[2]));

                foreach (Box cell in BlockPhysicsData.CollisionBoxesOf(local)) {
                    shapes.Add(cell.Translate(s[6], s[7], s[8]));
                }
            }

            double[] b = Numbers(parts[1]);
            double[] m = Numbers(parts[2]);
            double[] r = Numbers(parts[3]);

            Box box = new(b[0], b[1], b[2], b[3], b[4], b[5]);
            Vec3<double> result = EntityPhysics.CollideWithShapes(new Vec3<double>(m[0], m[1], m[2]), box, shapes);

            Assert.Multiple(() => {
                Assert.That(result.X, Is.EqualTo(r[0]), $"X of {line}");
                Assert.That(result.Y, Is.EqualTo(r[1]), $"Y of {line}");
                Assert.That(result.Z, Is.EqualTo(r[2]), $"Z of {line}");
            });
        }
    }

    private static double[] Numbers(string csv) {
        return csv.Split(',').Select(s => double.Parse(s, CultureInfo.InvariantCulture)).ToArray();
    }
